?php endforeach;?><a href="/tool.php">View All Tools →</a></aside></div></main><?php require_once __DIR__.'/../footer.php';?><script>document.getElementById('calc').onclick=()=>{const s=document.getElementById('dob').value,o=document.getElementById('out');if(!s){o.textContent='Please select your date of birth.';return}const d=new Date(s+'T00:00:00'),n=new Date();if(d>n){o.textContent='Date of birth cannot be in the future.';return}let y=n.getFullYear()-d.getFullYear(),m=n.getMonth()-d.getMonth(),day=n.getDate()-d.getDate();if(day<0){m--;day+=new Date(n.getFullYear(),n.getMonth(),0).getDate()}if(m<0){y--;m+=12}o.innerHTML='<strong>'+y+' years, '+m+' months, '+day+' days</strong>'}</script></body></html>